#!/usr/bin/env python3
"""Chrome DevTools Protocol helper."""
import json
import sys
import time
import urllib.request
import websocket

DEBUG_PORT = 1337


def get_page_target(url_substr=None):
    data = json.loads(urllib.request.urlopen(f"http://localhost:{DEBUG_PORT}/json").read())
    pages = [t for t in data if t.get("type") == "page"]
    if url_substr:
        for p in pages:
            if url_substr in p.get("url", ""):
                return p
    return pages[0] if pages else None


class CDP:
    def __init__(self, ws_url):
        self.ws = websocket.create_connection(ws_url, timeout=30)
        self.id = 0

    def send(self, method, params=None, timeout=30):
        self.id += 1
        msg = {"id": self.id, "method": method, "params": params or {}}
        self.ws.send(json.dumps(msg))
        self.ws.settimeout(timeout)
        while True:
            resp = json.loads(self.ws.recv())
            if resp.get("id") == self.id:
                if "error" in resp:
                    raise RuntimeError(f"CDP error in {method}: {resp['error']}")
                return resp.get("result", {})

    def eval(self, expr, await_promise=True, timeout=30):
        r = self.send(
            "Runtime.evaluate",
            {
                "expression": expr,
                "awaitPromise": await_promise,
                "returnByValue": True,
            },
            timeout=timeout,
        )
        if "exceptionDetails" in r:
            raise RuntimeError(f"JS error: {r['exceptionDetails']}")
        return r.get("result", {}).get("value")

    def close(self):
        self.ws.close()


def connect(url_substr=None):
    t = get_page_target(url_substr)
    if not t:
        print("No page target found", file=sys.stderr)
        sys.exit(1)
    return CDP(t["webSocketDebuggerUrl"])


if __name__ == "__main__":
    cdp = connect()
    expr = sys.argv[1] if len(sys.argv) > 1 else "document.title"
    print(json.dumps(cdp.eval(expr), indent=2))
    cdp.close()

