"""Higher-level CDP helpers for input simulation."""
import os, sys, time
sys.path.insert(0, "/tmp")
from cdp import connect


def dispatch_key(cdp, type_, key, code=None, text=None, modifiers=0):
    params = {"type": type_, "key": key, "modifiers": modifiers}
    if code is not None:
        params["code"] = code
    if text is not None:
        params["text"] = text
    cdp.send("Input.dispatchKeyEvent", params)


def type_text(cdp, text):
    for ch in text:
        cdp.send("Input.insertText", {"text": ch})
        time.sleep(0.03)


def click_at(cdp, x, y):
    for type_ in ("mousePressed", "mouseReleased"):
        cdp.send("Input.dispatchMouseEvent", {
            "type": type_, "x": x, "y": y, "button": "left", "clickCount": 1
        })


def get_rect(cdp, selector):
    js = f"""
    (() => {{
      const el = document.querySelector({selector!r});
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return {{x: r.x + r.width/2, y: r.y + r.height/2, w: r.width, h: r.height,
              left: r.left, top: r.top, right: r.right, bottom: r.bottom}};
    }})()
    """
    return cdp.eval(js)


def click_selector(cdp, selector):
    rect = get_rect(cdp, selector)
    if not rect:
        raise RuntimeError(f"Selector not found: {selector}")
    click_at(cdp, rect["x"], rect["y"])
    return rect


def wait_for(cdp, expr, timeout=15, interval=0.5):
    deadline = time.time() + timeout
    while time.time() < deadline:
        if cdp.eval(expr):
            return True
        time.sleep(interval)
    return False

