  const headings = [...dialog.querySelectorAll('h1,h2,h3,h4,[class*="month"]')].map(h => (h.innerText||'').trim());
  // sample dialog snippet
  const snippet = dialog.innerHTML.slice(0, 800);
  return {tables: result, headings: headings.slice(0,10), snippet};
})()
""")
print(json.dumps(out, indent=2))
