#!/usr/bin/env python3
"""Click May 11 then May 15 on the calendar."""
import sys, time, json
sys.path.insert(0, "/tmp")
from cdp import connect
from cdp_helpers import click_at

cdp = connect("rentalcars.com")


def click_day(day_text, month_label):
    rect = cdp.eval(f"""
    (() => {{
      // find table whose header indicates the right month
      const dialog = document.querySelector('[role="dialog"]');
      if (!dialog) return null;
      // the month name is in the heading near the table
      const tables = [...dialog.querySelectorAll('table')];
      let target = null;
      for (const t of tables) {{
        // look for a sibling/ancestor element with the month label
        let p = t.parentElement;
        for (let i=0; i<5 && p; i++, p=p.parentElement) {{
          if ((p.innerText||'').includes({month_label!r})) {{
            target = t;
            break;
          }}
        }}
        if (target === t) break;
      }}
      if (!target) target = tables[0];
      const cells = [...target.querySelectorAll('td')];
      // pick first td whose text matches
      for (const td of cells) {{
        if ((td.innerText||'').trim() === {day_text!r}) {{
          if (td.getAttribute('aria-disabled') === 'true') continue;
          const r = td.getBoundingClientRect();
          return {{x: r.x + r.width/2, y: r.y + r.height/2}};
        }}
      }}
      return null;
    }})()
    """)
    if not rect:
        raise RuntimeError(f"day {day_text} in {month_label} not found")
    print(f"clicking {day_text} {month_label}:", rect)
    click_at(cdp, rect["x"], rect["y"])
    time.sleep(0.6)


# Pick May 11 (pickup)
click_day("11", "May 2026")
# Pick May 15 (drop-off)
click_day("15", "May 2026")
time.sleep(1)

# Inspect dates buttons text after selection
state = cdp.eval("""
(() => {
  const btns = [...document.querySelectorAll('button')]
    .filter(b => ['Choose Pick-up Date','Choose Drop-off Date'].includes(b.getAttribute('aria-label')));
  return btns.map(b => ({aria: b.getAttribute('aria-label'), text: (b.innerText||'').trim()}));
})()
""")
print(json.dumps(state, indent=2))
cdp.close()

