#!/usr/bin/env python3
"""Wait for results page and inspect filters."""
import sys, time, json
sys.path.insert(0, "/tmp")
from cdp import connect
from cdp_helpers import wait_for

cdp = connect("rentalcars.com")

# Wait for results to load
print("waiting for results...")
ok = wait_for(cdp, "document.querySelector('[class*=\"car\"], [data-testid*=\"car\"]') !== null", timeout=30)
print("results loaded:", ok)
time.sleep(3)

# Inspect filters and sort options
out = cdp.eval("""
(() => {
  // collect filter labels
  const filters = [...document.querySelectorAll('label, [role="checkbox"], [data-testid*="filter" i]')]
    .map(el => (el.innerText || el.getAttribute('aria-label') || '').trim().slice(0,80))
    .filter(t => t)
    .slice(0, 100);
  // collect sort dropdown
  const sortBtns = [...document.querySelectorAll('button, select, [role="button"]')]
    .filter(b => /sort/i.test(b.innerText || b.getAttribute('aria-label') || ''))
    .map(b => ({text: (b.innerText||'').trim().slice(0,60),
                aria: b.getAttribute('aria-label'),
                tag: b.tagName}));
  // see how many car results
  const carCards = document.querySelectorAll('[data-testid*="car-card" i], [class*="search-result-card" i], [class*="vehicle-card" i]').length;
  return {filters, sortBtns, carCards, title: document.title};
})()
""")
print(json.dumps(out, indent=2)[:5000])
cdp.close()

