#!/usr/bin/env python3
"""Click the 'Large car' filter."""
import sys, time, json
sys.path.insert(0, "/tmp")
from cdp import connect
from cdp_helpers import click_at

cdp = connect("rentalcars.com")

rect = cdp.eval("""
(() => {
  // Find the label element with text 'Large car' (followed by digits)
  const labels = [...document.querySelectorAll('label')];
  for (const l of labels) {
    const t = (l.innerText || '').trim();
    if (/^Large car\\s*\\d*$/i.test(t.split('\\n')[0]) || t.startsWith('Large car ')) {
      l.scrollIntoView({block: 'center'});
      const r = l.getBoundingClientRect();
      return {x: r.x + r.width/2, y: r.y + r.height/2, text: t};
    }
  }
  return null;
})()
""")
print("large car filter:", rect)
time.sleep(0.5)
click_at(cdp, rect["x"], rect["y"])
time.sleep(2.5)

# verify by checking applied filters / count
state = cdp.eval("""
(() => {
  // look for "Large car" in active filter chips
  const chips = [...document.querySelectorAll('button, [class*="chip" i], [class*="filter" i]')]
    .map(b => (b.innerText || '').trim()).filter(t => t.includes('Large'));
  // result count
  const heading = (document.querySelector('h1, [data-testid*="result"]')?.innerText || '').trim().slice(0,120);
  return {chips: chips.slice(0,10), heading};
})()
""")
print(json.dumps(state, indent=2))
cdp.close()

