(() => {
  // Find elements that contain "Total price" or per-day prices
  const all = [...document.querySelectorAll('*')];
  const candidates = all.filter(el => /Total price|per day/i.test(el.innerText || '') && el.children.length < 30);
  // group by tag/class
  const map = new Map();
  for (const el of candidates) {
    const key = el.tagName + '|' + (el.className||'').slice(0,40);
    map.set(key, (map.get(key)||0)+1);
  }
  return [...map.entries()].sort((a,b)=>b[1]-a[1]).slice(0,10);
})()
