(() => {
  // Find buttons that take user to deal/booking
  const btns = [...document.querySelectorAll('a, button')]
    .filter(b => /view deal|choose|book/i.test((b.innerText||'').trim()))
    .slice(0,5);
  // For each button, walk up to a card-ish ancestor (containing price and image maybe)
  return btns.map(b => {
    let p = b.parentElement;
    let last = null;
    for (let i=0; i<10 && p; i++, p=p.parentElement) {
      if ((p.innerText||'').match(/\$\s*[\d,]+/) && p.querySelector('img')) {
        last = p;
      }
      if (last && p !== last) break;
    }
    if (!last) return {btn: b.innerText};
    const lines = (last.innerText||'').split('\n').map(s=>s.trim()).filter(Boolean).slice(0,12);
    return {btn: b.innerText.trim(), lines, tag: last.tagName, cls: last.className.slice(0,60)};
  });
})()
